    $intro=is_array($record['profile']??null)?(string)($record['profile']['Resumen para ficha']??''):'';
    $ready=trim($style)!==''&&trim($intro)!==''&&$steps>0&&$illustrated===$steps
        &&$fullBoards===count($routes);
